import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BsW8vZXt.js";const b=JSON.parse('{"title":"What is mobx-data?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-mobx-data.md","filePath":"guide/what-is-mobx-data.md"}'),d={name:"guide/what-is-mobx-data.md"};function s(n,e,i,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="what-is-mobx-data" tabindex="-1">What is mobx-data? <a class="header-anchor" href="#what-is-mobx-data" aria-label="Permalink to &quot;What is mobx-data?&quot;">​</a></h1><p><strong>mobx-data</strong> is a feature-complete port of <a href="https://guides.emberjs.com/release/models/" target="_blank" rel="noreferrer">Ember Data</a> to MobX. It provides the same battle-tested data-layer patterns — Identity Map, pluggable adapters and serializers, record state machines, and async relationships — but powered by MobX observables instead of Ember&#39;s computed property system.</p><h2 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why?&quot;">​</a></h2><p>Ember Data solved the hardest problems of client-side data management years ago:</p><ul><li><strong>Identity</strong> — one record, one object. No stale copies floating around.</li><li><strong>Protocol abstraction</strong> — swap REST for JSON:API without touching your components.</li><li><strong>Lifecycle management</strong> — know exactly whether a record is loading, dirty, saving, or errored.</li><li><strong>Relationship resolution</strong> — traverse a record graph without manually wiring up fetches.</li></ul><p>But Ember Data is locked to the Ember framework. mobx-data brings these patterns to any app that uses MobX.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Framework-agnostic</strong></td><td>React, Vue, Solid, Svelte, plain JS — if MobX runs there, mobx-data does too</td></tr><tr><td><strong>Observable all the way down</strong></td><td>Every piece of state is a MobX observable — no glue code needed</td></tr><tr><td><strong>TypeScript-first</strong></td><td>Full generic types, decorator metadata, strict mode</td></tr><tr><td><strong>Modular</strong></td><td>Import only the pieces you need: <code>mobx-data/store</code>, <code>mobx-data/json-api</code>, etc.</td></tr><tr><td><strong>Familiar</strong></td><td>If you&#39;ve used Ember Data, you already know the API</td></tr></tbody></table><h2 id="comparison-with-ember-data" tabindex="-1">Comparison with Ember Data <a class="header-anchor" href="#comparison-with-ember-data" aria-label="Permalink to &quot;Comparison with Ember Data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ember Data</th><th>mobx-data</th><th>Notes</th></tr></thead><tbody><tr><td><code>DS.Model</code></td><td><code>Model</code></td><td>MobX <code>@observable</code> fields</td></tr><tr><td><code>DS.Store</code></td><td><code>Store</code></td><td><code>observable.map</code> identity map</td></tr><tr><td><code>DS.Adapter</code></td><td><code>Adapter</code></td><td>Same interface, async/await</td></tr><tr><td><code>DS.Serializer</code></td><td><code>Serializer</code></td><td>Same interface</td></tr><tr><td><code>DS.Transform</code></td><td><code>Transform</code></td><td>Same interface</td></tr><tr><td><code>DS.Errors</code></td><td><code>Errors</code></td><td><code>observable.map</code> of field errors</td></tr><tr><td><code>RecordArray</code></td><td><code>RecordArray</code></td><td><code>observable.array</code></td></tr><tr><td><code>RequestManager</code></td><td><code>RequestManager</code></td><td>Handler chain pattern</td></tr><tr><td><code>SchemaDefinitionService</code></td><td><code>SchemaService</code></td><td>Same interface</td></tr></tbody></table><h2 id="when-to-use-mobx-data" tabindex="-1">When to Use mobx-data <a class="header-anchor" href="#when-to-use-mobx-data" aria-label="Permalink to &quot;When to Use mobx-data&quot;">​</a></h2><p>mobx-data is a great fit when:</p><ul><li>Your app talks to a REST or JSON:API backend and you want structured data management</li><li>You already use MobX and want a data layer that integrates seamlessly</li><li>You need dirty tracking, rollback, and lifecycle hooks</li><li>You&#39;re migrating from Ember and want to keep the familiar data patterns</li><li>You want a single source of truth (Identity Map) across your entire app</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                       Your App                           │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│   Store  ←→  Model  ←→  StateMachine                    │</span></span>
<span class="line"><span>│     │                                                    │</span></span>
<span class="line"><span>│     ├── IdentityMap (observable cache)                   │</span></span>
<span class="line"><span>│     ├── Adapter (REST / JSON:API / OData / custom)       │</span></span>
<span class="line"><span>│     ├── Serializer (normalize / serialize)               │</span></span>
<span class="line"><span>│     └── RequestManager (middleware chain)                │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                     MobX Observables                     │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div>`,15)])])}const m=t(d,[["render",s]]);export{b as __pageData,m as default};
